package s3

import (
	"context"
	"net/url"
	"strings"
	"testing"
	"time"
)

// These signatures were independently generated by the existing offsite module's AWS SDK
// v1.48.0 signer, with DisableURIPathEscaping=true. No SDK dependency enters the root module.
func TestSignaturesMatchExistingAWSSigner(t *testing.T) {
	c, err := New(Config{Endpoint: "https://s3.example.test", Bucket: "bucket", AccessKey: testAccess, SecretKey: testSecret})
	if err != nil {
		t.Fatal(err)
	}
	key := "orgs/a/a b+%//../é"
	when := time.Date(2026, 11, 23, 1, 2, 3, 0, time.UTC)
	for _, test := range []struct {
		method, key string
		q           url.Values
		signature   string
	}{
		{"GET", key, versionQuery("v%2F+/=& space"), "354c1c3281da82a13bf279aa8d1aaac86046628fefb6a3b75c1549285870edfb"},
		{"PUT", key, nil, "33ca6e470d05f96b1329978258ea7f17b7a403519eb942fba40ea47c38ff64ce"},
		{"GET", "", url.Values{"encoding-type": {"url"}, "key-marker": {"orgs/a/key +%"}, "max-keys": {"1000"}, "prefix": {"orgs/a/"}, "version-id-marker": {"v%2F+/=& space"}, "versions": {""}}, "0a8611ae65ee7350bb86798ff30348d855736ff0ab2b3f407c2fc3d85581c740"},
	} {
		r, err := c.request(context.Background(), test.method, test.key, test.q, nil)
		if err != nil {
			t.Fatal(err)
		}
		c.sign(r, when)
		if !strings.HasSuffix(r.Header.Get("Authorization"), "Signature="+test.signature) {
			t.Errorf("signature mismatch for %s %s: %s", test.method, r.URL, r.Header.Get("Authorization"))
		}
	}
}
